void save(Shell&s,int n){auto*f=new QHBoxLayout;f->addWidget(single("ANIWORLD · Gestion du centre"));f->addStretch();f->addWidget(muted("1 octobre 2026"));s.v->addLayout(f);s.w->show();QApplication::processEvents();QThread::msleep(30);QApplication::processEvents();if(n==3||n==4){s.w->resize(s.w->width(),s.w->height()+34);QApplication::processEvents();}s.w->grab().save(output+QString("/gui_%1.png").arg(n));s.w->close();delete s.w;}

